create table public.report_schedule(id uuid primary key,cooperative_id uuid references public.cooperative,recipients text[] not null,enabled boolean not null default false,created_by uuid not null references public.membership,updated_at timestamptz not null default now());
alter table public.report_schedule enable row level security;
create policy report_schedule_read on public.report_schedule for select to authenticated using(created_by=auth.uid() or private.has_role(array['admin']) or private.can_operate(cooperative_id,array['manager']));
grant select on public.report_schedule to authenticated;
create trigger audit after insert or update on public.report_schedule for each row execute function private.audit_row();
create function public.save_report_schedule(target uuid,scope uuid,recipients text[],enabled boolean) returns void language plpgsql security definer set search_path='' as $$
begin
 if not (private.has_role(array['admin']) or scope is not null and private.can_operate(scope,array['manager'])) then raise exception 'Report schedule permission required';end if;
 if cardinality(recipients) not between 1 and 10 or exists(select 1 from unnest(recipients) email where email !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$') then raise exception 'Enter one to ten valid email recipients';end if;
 if exists(select 1 from public.report_schedule where id=target and created_by<>auth.uid()) and not private.has_role(array['admin']) then raise exception 'Schedule owner required';end if;
 insert into public.report_schedule(id,cooperative_id,recipients,enabled,created_by) values(target,scope,recipients,enabled,auth.uid()) on conflict(id) do update set cooperative_id=excluded.cooperative_id,recipients=excluded.recipients,enabled=excluded.enabled,updated_at=now();
end $$;
revoke all on function public.save_report_schedule(uuid,uuid,text[],boolean) from public,anon;
grant execute on function public.save_report_schedule(uuid,uuid,text[],boolean) to authenticated;
create table public.report_delivery(schedule_id uuid not null references public.report_schedule,period date not null,status text not null default 'pending' check(status in ('pending','sending','sent','failed')),attempts integer not null default 0,next_attempt_at timestamptz not null default now(),last_error text,sent_at timestamptz,primary key(schedule_id,period));
alter table public.report_delivery enable row level security;
create policy report_delivery_read on public.report_delivery for select to authenticated using(exists(select 1 from public.report_schedule s where s.id=schedule_id));
grant select on public.report_delivery to authenticated;

create function private.impact_metrics_core(from_date date,to_date date,scope uuid[],suppress_small_groups boolean) returns setof jsonb language plpgsql stable security definer set search_path='' as $$
declare period_start timestamptz:=from_date::timestamp at time zone 'Asia/Beirut';period_end timestamptz:=(to_date+1)::timestamp at time zone 'Asia/Beirut';participants integer;received numeric;accepted numeric;valorized numeric;packaged numeric;yield_output numeric;whey_input numeric;sales_value numeric;sold numeric;active_producers numeric;trained_producers numeric;completeness numeric;open_critical numeric;mock_minutes numeric;k record;metric numeric;
begin
 select count(distinct activity.author) into active_producers from (
  select producer_id author,cooperative_id,observed_at from public.lot where type='batch' and not coalesce((facts->>'test_data')::boolean,false)
  union all select r.author_id,r.cooperative_id,r.observed_at from public.operational_record r left join public.lot l on l.id=r.lot_id where not coalesce((r.payload->>'test_data')::boolean,false) and not coalesce((l.facts->>'test_data')::boolean,false)
  union all select c.author_id,c.cooperative_id,c.observed_at from public.consumption c join public.lot l on l.id=c.output_lot_id join public.lot i on i.id=c.input_lot_id where not coalesce((l.facts->>'test_data')::boolean,false) and not coalesce((i.facts->>'test_data')::boolean,false)
 ) activity join public.membership member on member.user_id=activity.author where member.status='active' and 'producer'=any(member.roles) and not coalesce((member.authorizations->>'test_data')::boolean,false) and activity.observed_at>=period_start and activity.observed_at<period_end and (scope is null or activity.cooperative_id=any(scope));
 participants:=active_producers;
 select coalesce(sum(l.initial_quantity),0),coalesce(sum(l.initial_quantity) filter(where private.whey_classification(l.id)='accepted'),0) into received,accepted from public.lot l where l.type='whey' and l.unit='kg' and not coalesce((l.facts->>'test_data')::boolean,false) and (scope is null or l.cooperative_id=any(scope)) and l.observed_at>=period_start and l.observed_at<period_end;
 select coalesce(sum(c.quantity),0) into valorized from public.consumption c join public.lot i on i.id=c.input_lot_id join public.lot o on o.id=c.output_lot_id where i.type='whey' and c.unit='kg' and private.whey_classification(i.id)='accepted' and o.type='batch' and o.state<>'rejected' and exists(select 1 from public.lot_state_event se where se.lot_id=o.id and se.state='released') and not coalesce((i.facts->>'test_data')::boolean,false) and not coalesce((o.facts->>'test_data')::boolean,false) and (scope is null or c.cooperative_id=any(scope)) and c.observed_at>=period_start and c.observed_at<period_end;
 select coalesce(sum(p.mass_kg),0) into packaged from public.packaging_detail p join public.lot b on b.id=p.batch_id join public.lot pl on pl.id=p.lot_id where b.state<>'rejected' and not coalesce((b.facts->>'test_data')::boolean,false) and (scope is null or p.cooperative_id=any(scope)) and pl.observed_at>=period_start and pl.observed_at<period_end;
 with complete_batches as (
  select b.id from public.lot b where b.type='batch' and b.state<>'rejected' and not coalesce((b.facts->>'test_data')::boolean,false) and (scope is null or b.cooperative_id=any(scope)) and exists(select 1 from public.consumption c join public.lot i on i.id=c.input_lot_id where c.output_lot_id=b.id and i.type='whey' and c.unit='kg') and not exists(select 1 from public.task t where t.lot_id=b.id and t.status='open' and t.kind='sync_conflict')
 ), outputs as (select p.batch_id,sum(p.mass_kg) mass from public.packaging_detail p join public.lot pl on pl.id=p.lot_id where p.batch_id in(select id from complete_batches) and pl.observed_at>=period_start and pl.observed_at<period_end group by p.batch_id)
 select coalesce(sum(outputs.mass),0),coalesce(sum((select sum(c.quantity) from public.consumption c join public.lot i on i.id=c.input_lot_id where c.output_lot_id=outputs.batch_id and i.type='whey' and c.unit='kg')),0) into yield_output,whey_input from outputs;
 select coalesce(sum(s.total/s.usd_rate),0),coalesce(sum(s.quantity),0) into sales_value,sold from public.sale s join public.lot pl on pl.id=s.packaging_lot_id join public.packaging_detail pd on pd.lot_id=pl.id join public.lot b on b.id=pd.batch_id where s.transaction_type='sale' and not coalesce((b.facts->>'test_data')::boolean,false) and not coalesce((pl.facts->>'test_data')::boolean,false) and (scope is null or s.cooperative_id=any(scope)) and s.observed_at>=period_start and s.observed_at<period_end;
 select count(*) into trained_producers from public.membership member join lateral(select cv.id from public.config_version cv where cv.kind='sop' and cv.status='approved' and cv.effective_at<period_end and (cv.cooperative_id is null or cv.cooperative_id=member.cooperative_id) order by (cv.cooperative_id is not null) desc,cv.version desc limit 1) current_config on true where member.status='active' and 'producer'=any(member.roles) and not coalesce((member.authorizations->>'test_data')::boolean,false) and (scope is null or member.cooperative_id=any(scope)) and exists(select 1 from public.training_module tm where tm.config_version_id=current_config.id and tm.required and tm.effective_at<period_end) and not exists(select 1 from public.training_module tm where tm.config_version_id=current_config.id and tm.required and tm.effective_at<period_end and not exists(select 1 from public.training_module newer where newer.config_version_id=tm.config_version_id and newer.module_key=tm.module_key and newer.version>tm.version and newer.effective_at<period_end) and not exists(select 1 from public.training_completion tc where tc.user_id=member.user_id and tc.module_id=tm.id and tc.completed_at<period_end and (tc.expires_at is null or tc.expires_at>=period_end)));
 completeness:=private.impact_completeness_filtered(period_start,period_end,scope);
 select count(*) into open_critical from public.deviation d left join public.lot l on l.id=d.lot_id where d.severity='critical' and d.observed_at<period_end and (d.closed_at is null or d.closed_at>=period_end) and not coalesce((l.facts->>'test_data')::boolean,false) and (scope is null or d.cooperative_id=any(scope));
 select avg(extract(epoch from completed_at-started_at)/60) into mock_minutes from public.recall where mock and completed_at>=period_start and completed_at<period_end and (scope is null or cooperative_id=any(scope));
 for k in select * from public.kpi_definition where not(suppress_small_groups) or visibility like '%donor%' order by id loop
  metric:=case k.id when 'KPI-01' then received when 'KPI-02' then accepted when 'KPI-03' then valorized when 'KPI-04' then 100*valorized/nullif(accepted,0) when 'KPI-05' then packaged when 'KPI-06' then yield_output/nullif(whey_input,0) when 'KPI-07' then active_producers when 'KPI-08' then trained_producers when 'KPI-09' then completeness when 'KPI-10' then sales_value when 'KPI-11' then sold when 'KPI-12' then open_critical when 'KPI-13' then mock_minutes else null end;
  return next jsonb_build_object('id',k.id,'label',k.label,'definition',k.definition,'source',k.source,'calculation',k.calculation,'exclusions',k.exclusions,'value',case when suppress_small_groups and participants<5 then null else metric end,'suppressed',(suppress_small_groups and participants<5),'unit',case when k.id in ('KPI-01','KPI-02','KPI-03','KPI-05') then 'kg' when k.id in ('KPI-04','KPI-09') then '%' when k.id='KPI-10' then 'USD' when k.id='KPI-13' then 'min' else '' end);
 end loop;
end $$;
create or replace function private.impact_metrics_filtered(from_date date,to_date date,cooperative_filter uuid,region_filter text) returns setof jsonb language plpgsql stable security definer set search_path='' as $$
declare m public.membership;scope uuid[];begin
 select * into m from public.membership where user_id=auth.uid() and status='active';
 if m.user_id is null or not private.has_role(array['manager','admin','food_safety','partner','donor']) then raise exception 'Dashboard permission required';end if;
 if not(m.roles&&array['admin','food_safety','partner','donor']) and cooperative_filter is not null and cooperative_filter is distinct from m.cooperative_id then raise exception 'Cooperative outside dashboard scope';end if;
 select coalesce(array_agg(c.id),'{}'::uuid[]) into scope from public.cooperative c where (m.roles&&array['admin','food_safety','partner','donor'] or c.id=m.cooperative_id) and (cooperative_filter is null or c.id=cooperative_filter) and (region_filter is null or c.region=region_filter);
 return query select * from private.impact_metrics_core(from_date,to_date,scope,'donor'=any(m.roles));
end $$;

revoke all on function private.impact_metrics_core(date,date,uuid[],boolean) from public,anon,authenticated;
create function public.claim_monthly_reports() returns setof jsonb language plpgsql security definer set search_path='' as $$
declare job record;scope uuid[];metrics jsonb;operations jsonb;period_start date:=(date_trunc('month',now() at time zone 'Asia/Beirut')-interval '1 month')::date;begin
 insert into public.report_delivery(schedule_id,period) select id,period_start from public.report_schedule where enabled on conflict do nothing;
 for job in select q.*,s.recipients,s.cooperative_id from public.report_delivery q join public.report_schedule s on s.id=q.schedule_id join public.membership m on m.user_id=s.created_by where s.enabled and m.status='active' and (m.roles&&array['admin'] or m.roles&&array['manager'] and m.cooperative_id=s.cooperative_id) and q.status in ('pending','sending','failed') and q.attempts<5 and q.next_attempt_at<=now() order by q.period limit 10 for update of q skip locked loop
 select array_agg(id) into scope from public.cooperative where job.cooperative_id is null or id=job.cooperative_id;
 select coalesce(jsonb_agg(metric),'[]') into metrics from private.impact_metrics_core(job.period,(job.period+interval '1 month'-interval '1 day')::date,scope,true) metric;
 select coalesce(jsonb_agg(row),'[]') into operations from (select c.name cooperative,c.region,(select count(*) from public.lot l where l.cooperative_id=c.id and l.type='batch' and l.observed_at>=job.period::timestamp at time zone 'Asia/Beirut' and l.observed_at<(job.period+interval '1 month') at time zone 'Asia/Beirut' and not coalesce((l.facts->>'test_data')::boolean,false)) batches,(select count(*) from public.deviation d where d.cooperative_id=c.id and d.closed_at is null) open_deviations from public.cooperative c where c.id=any(scope)) row;
 update public.report_delivery set status='sending',attempts=attempts+1,next_attempt_at=now()+interval '5 minutes' where schedule_id=job.schedule_id and period=job.period;
 return next jsonb_build_object('schedule_id',job.schedule_id,'period',job.period,'recipients',job.recipients,'impact',metrics,'operations',operations);
 end loop;
end $$;
revoke all on function public.claim_monthly_reports() from public,anon,authenticated;
grant execute on function public.claim_monthly_reports() to service_role;
